/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		propName: "deflection_configurations_enabled",
		value: event.payload.value
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const deflectionConfig = api.state.deflection_configurations_enabled;
    const deflectionConfigRecord = api.data.look_up_deflection_tracking_record.results[0];
    if (deflectionConfig == deflectionConfigRecord.value.displayValue)
        return {};

    const recordId = deflectionConfigRecord._row_data.uniqueValue;
    const fieldVlaues = 'value=' + deflectionConfig;

	return {
		table: 'sys_properties',
        recordId: recordId,
        templateFields: fieldVlaues,
        useSetDisplayValue: null
	};
}
